use std::env;
use std::fs;
use std::io;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len()!= 3 {
        println!("Usage: {} <pattern> <file>", args[0]);
        return;
    }

    let pattern = &args[1];
    let file_path = &args[2];

    match search_substring_in_file(pattern, file_path) {
        Ok(_) => println!("Search completed successfully!"),
        Err(e) => println!("Error: {}", e),
    }
}

fn search_substring_in_file(pattern: &str, file_path: &str) -> Result<(), String> {
    match fs::read_to_string(file_path) {
        Ok(content) => {
            let lines = content.lines();
            for line in lines {
                if line.contains(pattern) {
                    println!("{}: {}", file_path, line);
                }
            }
            Ok(())
        },
        Err(e) => Err(format!("Error reading file: {}", e)),
    }
}
```

